except ImportError:
    print("PyPDF2 is not available")

try:
    from PyPDF2 import PdfReader, PdfWriter
    print("PdfReader and PdfWriter are available")
except ImportError:
    print("PdfReader and PdfWriter are not available")

try:
    from PyPDF2 import PdfFileReader, PdfFileWriter
